import { useState } from 'react';

export default function PasskeyButton({ isAuthenticated, account, username, onSignup, onLogin, onLogout }) {
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);

  const handleSignup = async () => {
    const name = window.prompt('Choose a username for your passkey account:');
    if (!name) return;
    setLoading(true);
    setError(null);
    try {
      await onSignup(name);
    } catch (err) {
      setError(err.message);
    }
    setLoading(false);
  };

  const handleLogin = async () => {
    setLoading(true);
    setError(null);
    try {
      await onLogin();
    } catch (err) {
      setError(err.message);
    }
    setLoading(false);
  };

  if (isAuthenticated) {
    return (
      <div className="passkey-status">
        <span className="passkey-badge" title={account}>
          {username || account?.slice(0, 6) + '...' + account?.slice(-4)}
        </span>
        <button className="passkey-logout" onClick={onLogout}>Logout</button>
      </div>
    );
  }

  return (
    <div className="passkey-auth">
      {error && <span className="passkey-error" title={error}>!</span>}
      <button className="passkey-btn" onClick={handleSignup} disabled={loading}>
        {loading ? '...' : 'Sign Up'}
      </button>
      <button className="passkey-btn passkey-btn-secondary" onClick={handleLogin} disabled={loading}>
        {loading ? '...' : 'Login'}
      </button>
    </div>
  );
}

