 77→// FEN character to piece number mapping
 78→const FEN_TO_PIECE = {
 79→  'K': 1,   // White King
 80→  'P': 2,   // White Pawn
 81→  'N': 3,   // White Knight
 82→  'R': 4,   // White Rook
