  1→// Chess Engine using Stockfish.js
  2→import { PIECE_TYPES, isWhitePiece } from './constants';
  3→import { indexToRowCol, rowColToIndex } from './moveValidation';
  4→
  5→class ChessEngine {
  6→  constructor() {
  7→    this.engine = null;
  8→    this.isReady = false;
  9→    this.skillLevel = 10; // 0-20, where 20 is strongest
 10→  }
 11→
 12→  async init() {
 13→    return new Promise((resolve) => {
 14→      // Check WebAssembly support
 15→      const wasmSupported = typeof WebAssembly === 'object' &&
 16→        WebAssembly.validate(Uint8Array.of(0x0, 0x61, 0x73, 0x6d, 0x01, 0x00, 0x00, 0x00));
 17→
 18→      // Create Web Worker with stockfish
 19→      const workerPath = wasmSupported
 20→        ? '/stockfish.wasm.js'
 21→        : '/stockfish.js';
 22→
 23→      this.engine = new Worker(workerPath);
 24→
 25→      this.engine.addEventListener('message', (e) => {
 26→        const msg = e.data;
 27→        console.log('Stockfish:', msg);
 28→        if (msg === 'readyok') {
 29→          this.isReady = true;
 30→          resolve();
 31→        }
 32→      });
 33→
 34→      // Initialize engine
 35→      this.engine.postMessage('uci');
 36→      this.engine.postMessage(`setoption name Skill Level value ${this.skillLevel}`);
 37→      this.engine.postMessage('isready');
 38→    });
 39→  }
 40→
 41→  setSkillLevel(level) {
 42→    // level: 0-20 (0 = weakest, 20 = strongest)
 43→    this.skillLevel = Math.max(0, Math.min(20, level));
 44→    if (this.engine) {
 45→      this.engine.postMessage(`setoption name Skill Level value ${this.skillLevel}`);
 46→    }
 47→  }
 48→
 49→  // Convert board array to FEN notation
 50→  boardToFEN(board, currentTurn, halfMoveClock, fullMoveNumber = 1, castlingRights = 'KQkq', enPassantTarget = null) {
 51→    let fen = '';
 52→
 53→    // Piece placement
 54→    for (let row = 0; row < 8; row++) {
 55→      let emptyCount = 0;
 56→      for (let col = 0; col < 8; col++) {
 57→        const piece = board[row * 8 + col];
 58→        if (piece === 0) {
 59→          emptyCount++;
 60→        } else {
 61→          if (emptyCount > 0) {
 62→            fen += emptyCount;
 63→            emptyCount = 0;
 64→          }
 65→          const pieceType = Math.abs(piece);
 66→          const isWhite = isWhitePiece(piece);
 67→
 68→          let pieceChar = '';
 69→          switch (pieceType) {
 70→            case PIECE_TYPES.KING: pieceChar = 'k'; break;
 71→            case PIECE_TYPES.QUEEN: pieceChar = 'q'; break;
 72→            case PIECE_TYPES.ROOK: pieceChar = 'r'; break;
 73→            case PIECE_TYPES.BISHOP: pieceChar = 'b'; break;
 74→            case PIECE_TYPES.KNIGHT: pieceChar = 'n'; break;
 75→            case PIECE_TYPES.PAWN: pieceChar = 'p'; break;
 76→          }
 77→
 78→          fen += isWhite ? pieceChar.toUpperCase() : pieceChar;
 79→        }
 80→      }
 81→      if (emptyCount > 0) {
 82→        fen += emptyCount;
 83→      }
 84→      if (row < 7) fen += '/';
 85→    }
 86→
 87→    // Active color
 88→    fen += ' ' + (currentTurn === 'white' ? 'w' : 'b');
 89→
 90→    // Castling availability
 91→    fen += ' ' + castlingRights;
 92→
 93→    // En passant target
 94→    fen += ' ' + (enPassantTarget !== null ? this.indexToAlgebraic(enPassantTarget) : '-');
 95→
 96→    // Halfmove clock and fullmove number
 97→    fen += ` ${halfMoveClock} ${fullMoveNumber}`;
 98→
 99→    return fen;
100→  }
101→
102→  // Convert board index to algebraic notation (e.g., 0 -> a8, 63 -> h1)
103→  indexToAlgebraic(index) {
104→    const { row, col } = indexToRowCol(index);
105→    const file = String.fromCharCode(97 + col); // 'a' to 'h'
106→    const rank = 8 - row;
107→    return file + rank;
108→  }
109→
110→  // Convert algebraic notation to board index
111→  algebraicToIndex(algebraic) {
112→    const file = algebraic.charCodeAt(0) - 97; // 'a' = 0
113→    const rank = parseInt(algebraic[1]);
114→    const row = 8 - rank;
115→    return rowColToIndex(row, file);
116→  }
117→
118→  // Get best move from engine
119→  async getBestMove(board, currentTurn, halfMoveClock, castlingRights, enPassantTarget) {
120→    if (!this.isReady) {
121→      await this.init();
122→    }
123→
124→    return new Promise((resolve) => {
125→      const fen = this.boardToFEN(board, currentTurn, halfMoveClock, 1, castlingRights, enPassantTarget);
126→
127→      console.log('Position FEN:', fen);
128→
129→      const messageHandler = (e) => {
130→        const msg = e.data;
131→        console.log('Stockfish:', msg);
132→
133→        // Look for bestmove in response
134→        if (msg.startsWith('bestmove')) {
135→          const match = msg.match(/bestmove ([a-h][1-8])([a-h][1-8])([qrbn])?/);
136→          if (match) {
137→            const from = this.algebraicToIndex(match[1]);
138→            const to = this.algebraicToIndex(match[2]);
139→            const promotion = match[3]; // q, r, b, n or undefined
140→
141→            // Remove this handler
142→            this.engine.removeEventListener('message', messageHandler);
143→            resolve({ from, to, promotion });
144→          } else {
145→            this.engine.removeEventListener('message', messageHandler);
146→            resolve(null);
147→          }
148→        }
149→      };
150→
151→      this.engine.addEventListener('message', messageHandler);
152→
153→      // Send position and request move
154→      this.engine.postMessage('ucinewgame');
155→      this.engine.postMessage(`position fen ${fen}`);
156→      this.engine.postMessage('go movetime 1000'); // Think for 1 second
157→    });
158→  }
159→
160→  terminate() {
161→    if (this.engine) {
162→      this.engine.terminate();
163→      this.engine = null;
164→      this.isReady = false;
165→    }
166→  }
167→}
168→
169→export default ChessEngine;
