  1→import { useCallback } from 'react';
  2→import { encodeFunctionData } from 'viem';
  3→import { formatMoves } from './usePublishGame';
  4→import { chessLedgerAbi, CHESS_LEDGER_ADDRESS } from '../contracts/chessLedgerAbi';
  5→
  6→const API_BASE = 'http://localhost:3000';
  7→
  8→// --- Helpers (ported from demo.html) ---
  9→
 10→function bufToHex(buf) {
 11→  return '0x' + Array.from(new Uint8Array(buf)).map(b => b.toString(16).padStart(2, '0')).join('');
 12→}
 13→
 14→function hexToBytes(hex) {
 15→  hex = hex.startsWith('0x') ? hex.slice(2) : hex;
 16→  const bytes = new Uint8Array(hex.length / 2);
 17→  for (let i = 0; i < hex.length; i += 2) {
 18→    bytes[i / 2] = parseInt(hex.substr(i, 2), 16);
 19→  }
 20→  return bytes;
 21→}
 22→
 23→function parseDERSignature(signatureBytes) {
 24→  const sig = new Uint8Array(signatureBytes);
 25→  let offset = 0;
 26→
 27→  if (sig[offset++] !== 0x30) throw new Error('Invalid DER: missing SEQUENCE tag');
 28→  let totalLen = sig[offset++];
 29→  if (totalLen & 0x80) {
 30→    const numLenBytes = totalLen & 0x7f;
 31→    offset += numLenBytes;
 32→  }
 33→
 34→  // R
 35→  if (sig[offset++] !== 0x02) throw new Error('Invalid DER: missing INTEGER tag for r');
 36→  const rLen = sig[offset++];
 37→  let rBytes = sig.slice(offset, offset + rLen);
 38→  offset += rLen;
 39→  while (rBytes.length > 32 && rBytes[0] === 0x00) rBytes = rBytes.slice(1);
 40→  if (rBytes.length < 32) {
 41→    const padded = new Uint8Array(32);
 42→    padded.set(rBytes, 32 - rBytes.length);
 43→    rBytes = padded;
 44→  }
 45→
 46→  // S
 47→  if (sig[offset++] !== 0x02) throw new Error('Invalid DER: missing INTEGER tag for s');
 48→  const sLen = sig[offset++];
 49→  let sBytes = sig.slice(offset, offset + sLen);
 50→  while (sBytes.length > 32 && sBytes[0] === 0x00) sBytes = sBytes.slice(1);
 51→  if (sBytes.length < 32) {
 52→    const padded = new Uint8Array(32);
 53→    padded.set(sBytes, 32 - sBytes.length);
 54→    sBytes = padded;
 55→  }
 56→
 57→  return { r: bufToHex(rBytes), s: bufToHex(sBytes) };
 58→}
