 4→export function formatMoves(moveHistory) {
 5→  const parts = [];
 6→  for (let i = 0; i < moveHistory.length; i += 2) {
 7→    const num = Math.floor(i / 2) + 1;
 8→    const white = moveHistory[i];
 9→    const black = moveHistory[i + 1];
10→    parts.push(black ? `${num}. ${white} ${black}` : `${num}. ${white}`);
11→  }
12→  return parts.join(' ');
13→}
14→
15→export function usePublishGame() {
16→  const { isConnected } = useAccount();
17→  const { writeContractAsync, isPending } = useWriteContract();
18→
19→  const publishGame = async (game) => {
20→    if (!isConnected) {
21→      return { published: false, reason: 'wallet-not-connected' };
22→    }
23→
24→    if (!CHESS_LEDGER_ADDRESS) {
25→      console.warn('Chess ledger contract address not configured');
26→      return { published: false, reason: 'no-contract-address' };
27→    }
28→
29→    try {
30→      const movesString = formatMoves(game.moveHistory || []);
31→      const hash = await writeContractAsync({
32→        address: CHESS_LEDGER_ADDRESS,
33→        abi: chessLedgerAbi,
34→        functionName: 'publishGame',
35→        args: [game.id, game.result, movesString, game.engineColor],
36→      });
37→      return { published: true, txHash: hash };
38→    } catch (err) {
39→      console.error('Failed to publish game on-chain:', err);
40→      return { published: false, reason: 'tx-failed', error: err };
41→    }
42→  };
43→
44→  return { publishGame, isPending };
45→}
