### `server/middleware/auth.js`

**Exports**: `authenticateToken` middleware function

```js
const db = require('../db');

function authenticateToken(req, res, next) {
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    return res.status(401).json({ error: 'Missing or invalid Authorization header' });
  }

  const token = authHeader.slice(7);
  const user = db.prepare('SELECT id, username, passkey_address FROM users WHERE token = ?').get(token);

  if (!user) {
    return res.status(401).json({ error: 'Invalid token' });
  }

  req.user = user;
  next();
}

module.exports = { authenticateToken };
```

### `server/routes/auth.js`

**Exports**: Express Router

Endpoints:
- `POST /api/auth/signup` -- `{ username }` -> creates user, generates UUID token, returns `{ token, username }`
- `POST /api/auth/token` -- `{ passkeyAddress, username }` -> links passkey address to user, creates or returns token

```js
const { Router } = require('express');
const { v4: uuidv4 } = require('uuid');
const db = require('../db');

const router = Router();

router.post('/signup', (req, res) => {
  const { username } = req.body;
  if (!username || typeof username !== 'string' || !username.trim()) {
    return res.status(400).json({ error: 'Username required' });
  }

  const trimmed = username.trim();
  if (trimmed.length > 32) {
    return res.status(400).json({ error: 'Username too long (max 32 characters)' });
  }

  const token = uuidv4();

  try {
    const result = db.prepare('INSERT INTO users (username, token) VALUES (?, ?)').run(trimmed, token);
    res.json({ token, username: trimmed });
  } catch (err) {
    res.status(500).json({ error: 'Failed to create user' });
  }
});

router.post('/token', (req, res) => {
  const { passkeyAddress, username } = req.body;
  if (!passkeyAddress) {
    return res.status(400).json({ error: 'passkeyAddress required' });
  }

  // Check if user already exists with this passkey address
  let user = db.prepare('SELECT * FROM users WHERE passkey_address = ?').get(passkeyAddress);

  if (user) {
    return res.json({ token: user.token, username: user.username });
  }

  // Create new user linked to passkey
  const token = uuidv4();
  const name = username || passkeyAddress.slice(0, 10);

  db.prepare('INSERT INTO users (username, token, passkey_address) VALUES (?, ?, ?)')
    .run(name, token, passkeyAddress);

  res.json({ token, username: name });
});

module.exports = router;
```

