### `server/chess/stockfishPlayer.js`

**Exports**: `StockfishPlayer` class

Wraps the Stockfish CLI binary via `child_process.spawn`. Unlike the frontend's Web Worker approach, the server uses stdin/stdout:

```js
const { spawn } = require('child_process');

class StockfishPlayer {
  constructor(level = 10) {
    this.level = level;
    this.process = null;
  }

  start() {
    this.process = spawn('stockfish', [], { stdio: ['pipe', 'pipe', 'pipe'] });
    this._send('uci');
    this._send(`setoption name Skill Level value ${this.level}`);
    this._send('isready');
    // Wait for 'readyok' from stdout before proceeding
  }

  async getBestMove(fen) {
    return new Promise((resolve, reject) => {
      const timeout = setTimeout(() => reject(new Error('Stockfish timeout')), 10000);

      const handler = (data) => {
        const line = data.toString();
        const match = line.match(/bestmove ([a-h][1-8])([a-h][1-8])([qrbn])?/);
        if (match) {
          clearTimeout(timeout);
          this.process.stdout.off('data', handler);
          resolve({
            from: match[1],
            to: match[2],
            promotion: match[3] || null,
          });
        }
      };

      this.process.stdout.on('data', handler);
      this._send('ucinewgame');
      this._send(`position fen ${fen}`);
      this._send('go movetime 1000');
    });
  }

  _send(cmd) {
    if (this.process) this.process.stdin.write(cmd + '\n');
  }

  stop() {
    if (this.process) {
      this._send('quit');
      this.process.kill();
      this.process = null;
    }
  }
}
```

**Important**: Stockfish must be installed on the machine (`brew install stockfish` on macOS). The implementation should gracefully handle the case where Stockfish is not installed -- log a warning at startup and return an error if someone tries to create an AvE room.

