### `server/middleware/auth.js`

**Exports**: `authenticateToken` middleware function

```js
const db = require('../db');

function authenticateToken(req, res, next) {
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    return res.status(401).json({ error: 'Missing or invalid Authorization header' });
  }

  const token = authHeader.slice(7);
  const user = db.prepare('SELECT id, username, passkey_address FROM users WHERE token = ?').get(token);

  if (!user) {
    return res.status(401).json({ error: 'Invalid token' });
  }

  req.user = user;
  next();
}

module.exports = { authenticateToken };
```

### `server/routes/auth.js`

**Exports**: Express Router

Endpoints:
- `POST /api/auth/signup` -- `{ username }` -> creates user, generates UUID token, returns `{ token, username }`
- `POST /api/auth/token` -- `{ passkeyAddress, username }` -> links passkey address to user, creates or returns token

```js
const { Router } = require('express');
const { v4: uuidv4 } = require('uuid');
const db = require('../db');

const router = Router();

router.post('/signup', (req, res) => {
  const { username } = req.body;
  if (!username || typeof username !== 'string' || !username.trim()) {
    return res.status(400).json({ error: 'Username required' });
  }

  const trimmed = username.trim();
  if (trimmed.length > 32) {
    return res.status(400).json({ error: 'Username too long (max 32 characters)' });
  }

  const token = uuidv4();

  try {
    const result = db.prepare('INSERT INTO users (username, token) VALUES (?, ?)').run(trimmed, token);
    res.json({ token, username: trimmed });
  } catch (err) {
    res.status(500).json({ error: 'Failed to create user' });
  }
});

router.post('/token', (req, res) => {
  const { passkeyAddress, username } = req.body;
  if (!passkeyAddress) {
    return res.status(400).json({ error: 'passkeyAddress required' });
  }

  // Check if user already exists with this passkey address
  let user = db.prepare('SELECT * FROM users WHERE passkey_address = ?').get(passkeyAddress);

  if (user) {
    return res.json({ token: user.token, username: user.username });
  }

  // Create new user linked to passkey
  const token = uuidv4();
  const name = username || passkeyAddress.slice(0, 10);

  db.prepare('INSERT INTO users (username, token, passkey_address) VALUES (?, ?, ?)')
    .run(name, token, passkeyAddress);

  res.json({ token, username: name });
});

module.exports = router;
```

### `server/routes/rooms.js`

**Exports**: Express Router and a reference to the broadcast function (injected)

This is the most complex route file. Key functions:

**`POST /api/rooms`** -- Create a room:
1. Generate 6-char invite code (e.g., `ROOK42`)
2. Assign the creator to the chosen color
3. Create room row
4. Create initial game_state row
5. If `stockfishLevel` is set, mark as AvE and fill both player slots
6. Return `{ roomId, inviteCode, color }`

**`POST /api/rooms/join`** -- Join by invite code:
1. Look up room by invite code
2. Verify room status is `waiting`
3. Assign joiner to the empty color slot
4. Set status to `playing`
5. Return `{ roomId, color }`

**`GET /api/rooms/:id`** -- Get room state:
1. Load room and game_state
2. Deserialize board, compute FEN, compute legal moves for current player
3. Determine `myColor` based on `req.user.id`
4. Return full state payload

**`POST /api/rooms/:id/move`** -- Submit a move:
1. Parse the move string
2. Load and deserialize game state
3. Verify it's the player's turn and they're in the game
4. Call `isMoveLegal`, if illegal return `{ error, legalMoves }`
5. Call `applyMove`
6. Check `getGameResult`
7. Persist new state to SQLite
8. Broadcast `move` event via WebSocket
9. If game over, broadcast `gameOver` event, update room status
10. If AvE and it's now Stockfish's turn, trigger Stockfish move asynchronously
11. Return `{ ok: true, fen, gameOver?, result? }`

**Invite code generation**:
```js
function generateInviteCode() {
  const words = ['ROOK', 'KING', 'PAWN', 'MATE', 'MOVE', 'PLAY', 'GAME', 'DRAW'];
  const word = words[Math.floor(Math.random() * words.length)];
  const num = Math.floor(Math.random() * 90) + 10; // 10-99
  return word + num;
}
